const j=$json||{};
const store=$getWorkflowStaticData('global');
store.sessions=store.sessions||{};
const phone=j.phone||'';
const existing=store.sessions[phone];
const session=existing||{
  role:'unknown',
  orderReference:'',
  orderVerified:false,
  otpSentCount:0,
  otp:null,
  deliverySessionId:null,
  boxId:null,
  currentSubState:'START'
};
store.sessions[phone]=session;
const correlationId=j.correlationId||('LLB-'+Date.now()+'-'+Math.random().toString(36).slice(2,8));
return [{json:{...j, session, correlationId}}];

const j=$json||{};
const d=j.decision||{};
const store=$getWorkflowStaticData('global');
store.sessions=store.sessions||{};
const phone=j.phone||'';
const prev=store.sessions[phone]||{};
const upd=d.session_updates||{};
const newOrderRef=String(d.order_reference||'').trim();
const wrongOrderSignal=String(d.intent||'').toUpperCase()==='WRONG_ORDER';
const orderChanged=Boolean(newOrderRef && prev.orderReference && newOrderRef!==prev.orderReference);
const forceReset=wrongOrderSignal||orderChanged;
const merged={
  role:upd.role||prev.role||'unknown',
  orderReference: forceReset ? (wrongOrderSignal? '' : newOrderRef) : (newOrderRef||upd.orderReference||prev.orderReference||''),
  orderVerified: forceReset ? false : (typeof upd.orderVerified==='boolean'?upd.orderVerified:(prev.orderVerified||false)),
  otpSentCount: forceReset ? 0 : Number(upd.otpSentCount!=null?upd.otpSentCount:(prev.otpSentCount||0)),
  otp: forceReset ? null : (upd.otp!==undefined&&upd.otp!==''?upd.otp:(prev.otp||null)),
  deliverySessionId: forceReset ? null : (upd.deliverySessionId||prev.deliverySessionId||null),
  boxId: forceReset ? null : (upd.boxId!=null&&upd.boxId!==''?upd.boxId:(prev.boxId||null)),
  currentSubState: forceReset ? 'START' : (d.next_state||prev.currentSubState||'START')
};
store.sessions[phone]=merged;
return [{json:{...j, session:merged, orderResetTriggered:forceReset}}];

const j=$json||{};
const store=$getWorkflowStaticData('global');
store.rateLimit=store.rateLimit||{};
const phone=j.phone||'';
const now=Date.now();
const windowMs=60000;
const maxPerWindow=15;
const arr=(store.rateLimit[phone]||[]).filter(t=>now-t<windowMs);
arr.push(now);
store.rateLimit[phone]=arr;
const rateLimited=arr.length>maxPerWindow;
return [{json:{...j, rateLimited}}];

const j=$json||{};
const orig=$('Parse WhatsApp Payload').item.json;
const transcript=String(j.text||'').trim();
return [{json:{...orig, session:$('Load Session').item.json.session, correlationId:$('Load Session').item.json.correlationId, messageText:transcript||orig.messageText, mediaContext:'', reply_mode:'voice'}}];

const j=$json||{};
const d=j.decision||{};
const store=$getWorkflowStaticData('global');
store.audit=store.audit||[];
const entry={
  correlationId:j.correlationId||null,
  phone:j.phone||null,
  ts:new Date().toISOString(),
  intent:d.intent||null,
  action:d.action||null,
  orderReference:d.order_reference||null,
  nextState:d.next_state||null,
  orderResetTriggered:Boolean(j.orderResetTriggered),
  inputType:j.inputType||null,
  replyMode:j.reply_mode||'text'
};
store.audit.push(entry);
if(store.audit.length>500) store.audit.splice(0, store.audit.length-500);
console.log('LLBOX_AUDIT', JSON.stringify(entry));
return [{json:{...j}}];

const j=$json||{};
const status=Number(j.statusCode||200);
const body=j.data??j.body??'';
const text=typeof body==='string'?body:JSON.stringify(body);
if(status<200||status>=300||!text){
  return [{json:{...j, knowledgeRefreshed:false, knowledgeFetchError:'Fetch failed with status '+status+'; keeping previous cached content.'}}];
}
const store=$getWorkflowStaticData('global');
const now=Date.now();
const version='v'+now;
const hash=String(text.length)+'-'+now;
store.knowledge=store.knowledge||{};
store.knowledge.active={version,hash,fetchedAt:new Date(now).toISOString(),fetchedAtMs:now,content:text};
return [{json:{...j,knowledgeVersion:version,knowledgeHash:hash,knowledgeLastRefreshed:store.knowledge.active.fetchedAt,knowledgeContent:text,knowledgeStale:false,knowledgeRefreshed:true}}];
